#!/bin/bash\n\n# ============================================\n# 🚀 Arabic AI Lawyer for Oman - ONE COMMAND DEPLOY\n# ============================================\n\nset -e\n\necho \"🇴🇲 Arabic AI Lawyer for Oman\"\necho \"================================\"\necho \"\"\n\n# Check if Docker is installed\nif ! command -v docker &> /dev/null; then\n    echo \"❌ Docker not found. Please install Docker first.\"\n    echo \"   Visit: https://docs.docker.com/get-docker/\"\n    exit 1\nfi\n\n# Check if Docker Compose is installed\nif ! command -v docker-compose &> /dev/null; then\n    echo \"❌ Docker Compose not found. Please install Docker Compose first.\"\n    echo \"   Visit: https://docs.docker.com/compose/install/\"\n    exit 1\nfi\n\necho \"✅ Docker & Docker Compose found\"\necho \"\"\necho \"📦 Starting deployment...\"\necho \"\"\n\n# Pull latest changes\necho \"📥 Pulling latest code...\"\ngit pull origin main || true\necho \"\"\n\n# Start services\necho \"🐳 Starting Docker services...\"\ndocker-compose down -v 2>/dev/null || true\ndocker-compose up -d\n\necho \"\"\necho \"⏳ Waiting for services to start (30 seconds)...\"\nsleep 30\n\n# Check if services are running\necho \"\"\necho \"🔍 Checking service status...\"\necho \"\"\n\nif docker-compose ps | grep -q \"Up\"; then\n    echo \"✅ All services started successfully!\"\n    echo \"\"\n    echo \"🎯 ACCESS YOUR SERVICES:\"\n    echo \"\"\n    echo \"   🌐 Frontend (Arabic UI):    http://localhost:8501\"\n    echo \"   🔌 Backend API:             http://localhost:8000\"\n    echo \"   📚 API Documentation:       http://localhost:8000/docs\"\n    echo \"   🗄️  Database:                postgres://localhost:5432\"\n    echo \"   💾 Cache:                    redis://localhost:6379\"\n    echo \"\"\n    echo \"📖 DOCUMENTATION:\"\n    echo \"   • Quick Start:              cat QUICK_START.md\"\n    echo \"   • Installation:             cat docs/INSTALLATION.md\"\n    echo \"   • API Docs:                 http://localhost:8000/docs\"\n    echo \"   • Architecture:             cat docs/ARCHITECTURE.md\"\n    echo \"\"\n    echo \"🛑 TO STOP SERVICES:\"\n    echo \"   docker-compose down\"\n    echo \"\"\n    echo \"📊 TO VIEW LOGS:\"\n    echo \"   docker-compose logs -f backend\"\n    echo \"   docker-compose logs -f frontend\"\n    echo \"\"\n    echo \"✨ Ready to serve Omani legal queries! ⚖️\"\nelse\n    echo \"❌ Services failed to start. Checking logs...\"\n    echo \"\"\n    docker-compose logs\n    exit 1\nfi\n"